"""Generated by solo-to-scale; edit `templates/tools/notify.py` in the plugin, then run upgrade.

Tell the founder when something waits on them: the dashboard's Needs you list (approvals, escalations, blocked
and stuck work, budget stops, decisions, founder items), delivered by email through GitHub itself.

  python tools/notify.py push [--digest auto|now|off] [--mail-out DIR]

One issue labelled `needs-you` holds the current list and is assigned to the founder. When an item is new since
the last check, `push` comments on it mentioning the founder, and GitHub emails that mention (GitHub settings,
Notifications: "Participating, @mentions and custom": Email, which is on by default). Once a day, on the first run at or after
`notify.digest_hour_utc` in founder/dashboard.json (default 7), it posts the whole list as a digest, unless
nothing waits. No secret is needed. With `--mail-out`, it also writes `subject.txt` and `body.md` there and sets
`mail=yes` in $GITHUB_OUTPUT, for the optional SMTP step in the needs-you workflow.
Settings, in founder/dashboard.json (the deploy gate): "notify": {"enabled": true, "digest_hour_utc": 7}.
Python 3 standard library plus the gh CLI.
"""
from __future__ import annotations

import argparse
import datetime as dt
import json
import os
import re
import subprocess
import sys
from pathlib import Path
from typing import Any

sys.path.insert(0, str(Path(__file__).resolve().parent))
import _s2s as s  # noqa: E402
import approval  # noqa: E402
import build_dashboard as bd  # noqa: E402
import tickets  # noqa: E402

OK, ERROR = 0, 5
LABEL, TITLE = "needs-you", "Needs you"
SEEN = re.compile(r"<!-- s2s:seen (\[.*?\]) -->", re.DOTALL)
DIGEST = "<!-- s2s:digest "
DEFAULT_HOUR = 7
LIMIT = 40


def settings(root: Path) -> dict[str, Any]:
    got = bd.settings(root).get("notify")
    got = got if isinstance(got, dict) else {}
    hour = got.get("digest_hour_utc", DEFAULT_HOUR)
    return {"enabled": got.get("enabled", True) is not False,
            "digest_hour_utc": hour if isinstance(hour, int) and not isinstance(hour, bool) and 0 <= hour <= 23 else DEFAULT_HOUR}


def key(item: dict[str, Any]) -> str:
    return f"{item.get('kind')}:{item.get('number') or item.get('url') or item.get('title')}"


def line(item: dict[str, Any]) -> str:
    title = str(item.get("title") or "").replace("\n", " ")
    head = f"[{title}]({item['url']})" if str(item.get("url") or "").startswith("https://") else title
    level = f" **{item['level']}**" if item.get("level") in ("overdue", "escalated") else ""
    return f"- **{item.get('kind')}**{level}: {head}" + (f" ({item['detail']})" if item.get("detail") else "")


def body(items: list[dict[str, Any]], dashboard: str, seen: list[str]) -> str:
    rows = [line(x) for x in items[:LIMIT]] or ["Nothing waits on you."]
    more = [f"- and {len(items) - LIMIT} more on the dashboard"] if len(items) > LIMIT else []
    return "\n".join([
        "Everything waiting on you, kept current by `tools/notify.py` (the needs-you workflow). New items are"
        " mentioned in a comment, which GitHub emails you; a digest comes once a day.", "",
        *((f"Dashboard: {dashboard}", "") if dashboard else ()),
        *rows, *more, "", f"<!-- s2s:seen {json.dumps(seen)} -->"])


def dashboard_url(root: Path) -> str:
    host = str(bd.settings(root).get("host") or "")
    return f"https://{host}/#needs" if bd.HOST.match(host) else ""


def mentions(logins: set[str]) -> str:
    return " ".join(f"@{x}" for x in sorted(logins) if re.fullmatch(r"[A-Za-z0-9](?:[A-Za-z0-9-]{0,38})", x))


def inbox(hub: tickets.Hub, logins: set[str]) -> dict[str, Any]:
    found = [i for i in hub.tickets("open", LABEL)]
    if found:
        return found[0]
    return hub.api("issues", "-X", "POST", payload={"title": TITLE, "labels": [LABEL], "assignees": sorted(logins),
                                                    "body": body([], "", [])})


def digest_due(hub: tickets.Hub, n: int, now: dt.datetime, hour: int, mode: str) -> bool:
    if mode == "off" or (mode == "auto" and now.hour < hour):
        return False
    if mode == "now":
        return True
    today = now.strftime("%Y-%m-%d")
    recent = hub.api(f"issues/{n}/comments?per_page=100&since={today}T00:00:00Z") or []
    return not any(DIGEST + today in (c.get("body") or "") for c in recent)


def push(root: Path, hub: tickets.Hub, items: list[dict[str, Any]], now: dt.datetime, mode: str) -> dict[str, Any]:
    """Update the inbox issue; mention the founder for new items and for the daily digest. Returns what it sent."""
    logins = approval.founders(approval.policy(root), hub.repo)
    issue = inbox(hub, logins)
    n = issue["number"]
    m = SEEN.search(issue.get("body") or "")
    try:
        seen = set(json.loads(m.group(1))) if m else set()
    except ValueError:
        seen = set()
    keys = [key(x) for x in items]
    fresh = [x for x in items if key(x) not in seen]
    url = dashboard_url(root)
    hub.api(f"issues/{n}", "-X", "PATCH", payload={"body": body(items, url, keys), "assignees": sorted(logins)})
    sent: dict[str, Any] = {"issue": n, "new": len(fresh), "digest": False}
    who = mentions(logins)
    if fresh:
        text = "\n".join([f"{who} {len(fresh)} new thing{'s' if len(fresh) != 1 else ''} waiting on you:", "",
                          *[line(x) for x in fresh[:LIMIT]], *([f"Dashboard: {url}"] if url else [])])
        hub.comment(n, text)
        sent["subject"] = f"Needs you: {len(fresh)} new ({fresh[0].get('kind')}: {str(fresh[0].get('title'))[:60]})"
        sent["text"] = text
    if items and digest_due(hub, n, now, settings(root)["digest_hour_utc"], mode):
        text = "\n".join([f"{DIGEST}{now.strftime('%Y-%m-%d')} -->",
                          f"{who} Daily digest: {len(items)} thing{'s' if len(items) != 1 else ''} waiting on you"
                          + (f", {sum(x.get('level') != 'new' for x in items)} overdue" if any(x.get('level') != 'new' for x in items) else "")
                          + ".", "", *[line(x) for x in items[:LIMIT]], *([f"Dashboard: {url}"] if url else [])])
        hub.comment(n, text)
        sent["digest"] = True
        sent["subject"] = f"Needs you: {len(items)} waiting (daily digest)"
        sent["text"] = text
    return sent


def write_mail(out: Path, sent: dict[str, Any], github_output: str) -> None:
    if not sent.get("text"):
        return
    out.mkdir(parents=True, exist_ok=True)
    (out / "subject.txt").write_text(sent["subject"], encoding="utf-8")
    (out / "body.md").write_text(sent["text"].replace(DIGEST, "<!-- "), encoding="utf-8")
    if github_output:
        with open(github_output, "a", encoding="utf-8") as f:
            f.write("mail=yes\n")


def main(argv: list[str] | None = None) -> int:
    ap = argparse.ArgumentParser(description="Tell the founder what waits on them")
    ap.add_argument("--root", type=Path, default=s.ROOT, help=argparse.SUPPRESS)
    sub = ap.add_subparsers(dest="cmd", required=True)
    p = sub.add_parser("push")
    p.add_argument("--digest", choices=("auto", "now", "off"), default="auto")
    p.add_argument("--mail-out", type=Path)
    p.add_argument("--now", type=float, default=0, help=argparse.SUPPRESS)
    a = ap.parse_args(argv)
    if not settings(a.root)["enabled"]:
        print("notifications are off (founder/dashboard.json notify.enabled)")
        return OK
    repo = approval.repo_name(a.root)
    if not repo:
        print("can't tell which GitHub repo this is: nothing sent")
        return ERROR
    now = dt.datetime.fromtimestamp(a.now, dt.timezone.utc) if a.now else dt.datetime.now(dt.timezone.utc)
    data = bd.build(a.root, now=now)
    if not (data.get("github") or {}).get("ok"):
        print(f"GitHub unavailable ({(data.get('github') or {}).get('why', '?')}): nothing sent")
        return ERROR
    items = (data.get("needs") or {}).get("items") or []
    try:
        hub = tickets.Hub(repo)
        hub.root = a.root
        sent = push(a.root, hub, items, now, a.digest)
    except (subprocess.CalledProcessError, FileNotFoundError, ValueError, KeyError, TypeError) as exc:
        print(f"GitHub unavailable or unexpected reply ({type(exc).__name__}): nothing more is sent")
        return ERROR
    print(f"#{sent['issue']}: {len(items)} waiting, {sent['new']} new" + (", digest sent" if sent["digest"] else ""))
    if a.mail_out:
        write_mail(a.mail_out, sent, os.environ.get("GITHUB_OUTPUT", ""))
    return OK


if __name__ == "__main__":
    sys.exit(main())
